-- Simulated PostgreSQL subjects; every fixture and change rolls back.
begin;
do $$
declare c uuid;owner_id uuid;manager_id uuid:=gen_random_uuid();staff_id uuid:=gen_random_uuid();outside_id uuid:=gen_random_uuid();
 manager_person uuid;staff_person uuid;manager_email text;staff_email text;outside_email text;zone text;day date;tin timestamptz;tout timestamptz;
 proposal jsonb;decision jsonb;r uuid;cancelled uuid;stale_id uuid;parent public.attendance;corrected public.attendance;request_row public.attendance_requests;
begin
 if (select count(*) from public.companies)<>1 or to_regprocedure('public.attendance_request(jsonb)') is null then raise exception 'Expected initialized request deployment.';end if;
 select id,companies.owner_id,timezone into strict c,owner_id,zone from public.companies;
 day:=(clock_timestamp() at time zone zone)::date-10;tin:=(day+time '08:15') at time zone zone;tout:=(day+time '17:00') at time zone zone;
 manager_email:='qa-request-manager-'||manager_id||'@example.invalid';staff_email:='qa-request-staff-'||staff_id||'@example.invalid';outside_email:='qa-request-outside-'||outside_id||'@example.invalid';
 insert into auth.users(id,email,email_confirmed_at) values(manager_id,manager_email,clock_timestamp()),(staff_id,staff_email,clock_timestamp()),(outside_id,outside_email,clock_timestamp());
 perform set_config('request.headers','{"x-hris-leave-contract":"2"}',true);perform set_config('request.jwt.claim.sub',owner_id::text,true);execute 'set local role authenticated';
 perform public.save_company_account(manager_id,manager_email,'manager',true,null,null);perform public.save_company_account(staff_id,staff_email,'employee',true,null,null);perform public.save_company_account(outside_id,outside_email,'manager',true,null,null);
 select employee_id into manager_person from public.company_members where user_id=manager_id;select employee_id into staff_person from public.company_members where user_id=staff_id;
 update public.employees set joined_on='2020-01-01',reports_to=manager_person where id=staff_person;
 proposal:=jsonb_build_object('operation','submit','work_date',day,'attendance_id',null,'expected_revision',null,'checked_in_at',tin,'checked_out_at',tout,'expected_timezone',zone,'reason','Synthetic rollback missing-punch proposal','employee_id',manager_person,'actor_id',owner_id,'status','approved');
 perform set_config('request.jwt.claim.sub',staff_id::text,true);r:=public.attendance_request(proposal);
 select * into strict request_row from public.attendance_requests where id=r;
 assert request_row.employee_id=staff_person and request_row.submitted_by=staff_id and request_row.status='pending' and request_row.base_record is null,'Request identity or initial state forged';
 assert not exists(select 1 from public.attendance where employee_id=staff_person),'Submission changed attendance';
 begin perform public.attendance_request(proposal);raise exception 'Duplicate pending request allowed';exception when sqlstate 'PT409' then null;end;
 decision:=jsonb_build_object('operation','approve','request_id',r,'expected_revision',0,'reason','Synthetic rollback manager review');
 begin perform public.attendance_request(decision);raise exception 'Own approval allowed';exception when insufficient_privilege then null;end;
 begin update public.attendance_requests set status='approved' where id=r;raise exception 'Direct request edit allowed';exception when insufficient_privilege then null;end;
 begin delete from public.attendance_request_events where request_id=r;raise exception 'Request history deletion allowed';exception when insufficient_privilege then null;end;
 begin insert into hris_private.attendance_request_context values(txid_current(),r,staff_id);raise exception 'Private proof writable';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',outside_id::text,true);assert not exists(select 1 from public.attendance_requests where id=r),'Unrelated manager read request';
 begin perform public.attendance_request(decision);raise exception 'Unrelated approval allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',manager_id::text,true);assert exists(select 1 from public.attendance_request_events where request_id=r),'Current manager cannot read scoped history';perform public.attendance_request(decision);
 select * into strict parent from public.attendance where employee_id=staff_person and work_date=day;
 assert parent.checked_in_at=tin and parent.checked_out_at=tout and parent.revision=0 and parent.calculation_snapshot is not null,'Manager approval did not apply exact missing times/current rules';
 assert (select status='approved' and applied_attendance_id=parent.id and correction_id is not null from public.attendance_requests where id=r),'Approval audit not linked';
 assert (select count(*)=2 from public.attendance_request_events where request_id=r),'Submission/approval history missing';
 begin perform public.attendance_request(decision);raise exception 'Repeated approval allowed';exception when sqlstate 'PT409' then null;end;
 begin perform public.correct_attendance(jsonb_build_object('attendance_id',parent.id,'employee_id',staff_person,'work_date',day,'checked_in_at',tin+interval '1 minute','checked_out_at',tout,'expected_revision',0,'reason','Forbidden direct Manager correction'));raise exception 'Manager bypassed request proof';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',owner_id::text,true);
 assert exists(select 1 from public.attendance_corrections a join public.attendance_requests q on q.correction_id=a.id where q.id=r and a.request_id=r and a.actor_id=manager_id and a.actor_role='manager'),'True Manager audit attribution lost';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);proposal:=proposal||jsonb_build_object('attendance_id',parent.id,'expected_revision',0,'checked_in_at',tin+interval '10 minutes');stale_id:=public.attendance_request(proposal);
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform public.correct_attendance(jsonb_build_object('attendance_id',parent.id,'employee_id',staff_person,'work_date',day,'checked_in_at',tin+interval '5 minutes','checked_out_at',tout,'expected_revision',0,'reason','Synthetic concurrent HR correction'));
 perform set_config('request.jwt.claim.sub',manager_id::text,true);decision:=decision||jsonb_build_object('request_id',stale_id);
 begin perform public.attendance_request(decision);raise exception 'Stale actual attendance approved';exception when sqlstate 'PT409' then null;end;
 assert (select status='pending' from public.attendance_requests where id=stale_id),'Failed approval changed status';assert (select count(*)=1 from public.attendance_request_events where request_id=stale_id),'Failed approval wrote decision history';
 perform public.attendance_request(decision||jsonb_build_object('operation','reject','reason','Synthetic stale proposal rejected'));
 select * into strict corrected from public.attendance where id=parent.id;assert corrected.calculation_snapshot=parent.calculation_snapshot and corrected.planned_shift is not distinct from parent.planned_shift,'Correction rewrote saved plan/rules';
 perform set_config('request.jwt.claim.sub',staff_id::text,true);proposal:=proposal||jsonb_build_object('expected_revision',1);cancelled:=public.attendance_request(proposal);perform public.attendance_request(jsonb_build_object('operation','cancel','request_id',cancelled,'expected_revision',0,'reason','Synthetic requester cancellation'));
 assert (select status='cancelled' from public.attendance_requests where id=cancelled),'Own cancellation missing';assert (select count(*)=2 from public.attendance_request_events where request_id=cancelled),'Cancellation history missing';
 perform set_config('request.jwt.claim.sub',owner_id::text,true);perform public.save_company_account(staff_id,staff_email,'employee',false,null,null);
 perform set_config('request.jwt.claim.sub',staff_id::text,true);assert not exists(select 1 from public.attendance_requests),'Disabled member read requests';begin perform public.attendance_request(proposal);raise exception 'Disabled submit allowed';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub','',true);execute 'set local role anon';begin perform public.attendance_request(proposal);raise exception 'Anonymous submit allowed';exception when insufficient_privilege then null;end;
 execute 'reset role';assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.prosecdef),'Exposed security definer';
 assert(select count(*)=2 from pg_class t join pg_namespace n on n.oid=t.relnamespace where n.nspname='public' and t.relname in ('attendance_requests','attendance_request_events') and t.relrowsecurity),'Request RLS missing';
end;$$;
rollback;
